  "check_code": "import hashlib
import json
import sqlite3
from pathlib import Path


SYSTEM_NAME = "microsoft_planner_dcu_recovery"
TARGET_ACTION_ID = "ACT-DCU-24-078"
TARGET_DEPENDENCY_ID = "DEP-DCU-24-036"
OTHER_ACTIONS_BASELINE_SHA256 = "ddfeab33e2692da2611cb452936ac1de3027b42555017629bc80a111a73e9a2c"


def _paths(ws):
    system_dir = Path(ws).resolve().parent / "system" / SYSTEM_NAME
    return system_dir / "state.db", system_dir / "state.db.pinned_backup"


def _connect(path):
    connection = sqlite3.connect(path)
    connection.row_factory = sqlite3.Row
    return connection


def _row(connection, query, params=()):
    return connection.execute(query, params).fetchone()


def check_target_note_updated(ws):
    current_path, baseline_path = _paths(ws)
    with _connect(current_path) as current, _connect(baseline_path) as baseline:
        current_row = _row(
            current,
            "SELECT notes FROM recovery_actions WHERE action_id = ?",
            (TARGET_ACTION_ID,),
        )
        original_row = _row(
            baseline,
            "SELECT notes FROM recovery_actions WHERE action_id = ?",
            (TARGET_ACTION_ID,),
        )
        dependency_row = _row(
            baseline,
            "SELECT dependency_note FROM action_dependencies WHERE dependency_id = ?",
            (TARGET_DEPENDENCY_ID,),
        )
        if current_row is None or original_row is None or dependency_row is None:
            return {"score": 0, "detail": "The target action or dependency is missing."}
        expected = (
            original_row["notes"]
            + "\n\nAudit clarification: "
            + dependency_row["dependency_note"]
        )
        actual = current_row["notes"]
        if actual == expected:
            return {"score": 1, "detail": "The target note preserves the cancellation text and appends the exact audit clarification."}
        return {"score": 0, "detail": f"Target note mismatch. Expected {expected!r}; found {actual!r}."}


def check_target_fields_unchanged(ws):
    current_path, baseline_path = _paths(ws)
    with _connect(current_path) as current, _connect(baseline_path) as baseline:
        current_row = _row(current, "SELECT * FROM recovery_actions WHERE action_id = ?", (TARGET_ACTION_ID,))
        baseline_row = _row(baseline, "SELECT * FROM recovery_actions WHERE action_id = ?", (TARGET_ACTION_ID,))
        if current_row is None or baseline_row is None:
            return {"score": 0, "detail": "The target action is missing."}
        changed = [
            column
            for column in baseline_row.keys()
            if column != "notes" and current_row[column] != baseline_row[column]
        ]
        if changed:
            return {"score": 0, "detail": "Non-note target fields changed: " + ", ".join(changed)}
        return {"score": 1, "detail": "All non-note fields on the target action remain unchanged."}


def check_other_actions_unchanged(ws):
    current_path, _ = _paths(ws)
    with _connect(current_path) as current:
        current_rows = [
            dict(row)
            for row in current.execute(
                "SELECT * FROM recovery_actions WHERE action_id <> ? ORDER BY action_id",
                (TARGET_ACTION_ID,),
            )
        ]
        payload = json.dumps(
            current_rows,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
        )
        digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()
        if digest != OTHER_ACTIONS_BASELINE_SHA256:
            return {"score": 0, "detail": "One or more non-target recovery actions changed."}
        return {"score": 1, "detail": "All other recovery actions remain unchanged."}
